           MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_CLAIM|' || (nullif(trim(case when coalesce(nullif(trim(w1_claimno),''), nullif(trim("FOREIGN_KEY"),'')) is not null then coalesce(nullif(trim(w1_claimno), ''), nullif(trim("FOREIGN_KEY"), '')) end),'')) AS VARCHAR))), '')) as CLAIM_HKEY,
           MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (nullif(trim(case when coalesce(nullif(trim((nullif(trim(to_varchar("RESERVPARTY")), ''))),'')) is not null then nullif(trim((nullif(trim(to_varchar("RESERVPARTY")), ''))), '') end),'')) AS VARCHAR))), '')) as PARTY_HKEY
      from RAW.MAXIMUS_TRAVEL.NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_RESERVE
     where MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_CLAIM|' || (nullif(trim(case when coalesce(nullif(trim(w1_claimno),''), nullif(trim("FOREIGN_KEY"),'')) is not null then coalesce(nullif(trim(w1_claimno), ''), nullif(trim("FOREIGN_KEY"), '')) end),'')) AS VARCHAR))), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (nullif(trim(case when coalesce(nullif(trim((nullif(trim(to_varchar("RESERVPARTY")), ''))),'')) is not null then nullif(trim((nullif(trim(to_varchar("RESERVPARTY")), ''))), '') end),'')) AS VARCHAR))), '')) is not null
       and (claim_party_bk is not null)
    union all
    -- via lnkfeed_mt_claim_party <- stg2_mt__clm_clmd_clmpty
    select 'lnkfeed_mt_claim_party <- stg2_mt__clm_clmd_clmpty' as src_feed,
           MD5_BINARY(NULLIF(UPPER(TRIM(CAST('LNK_CLAIM_PARTY|' || (coalesce(nullif(trim(case when coalesce(nullif(trim(w0_claimno),''), nullif(trim("FOREIGN_KEY"),'')) is not null then coalesce(nullif(trim(w0_claimno), ''), nullif(trim("FOREIGN_KEY"), '')) end),''),'') || '|' || coalesce(nullif(trim(case when coalesce(nullif(trim((nullif(trim(to_varchar("PARTYCODE")), ''))),'')) is not null then nullif(trim((nullif(trim(to_varchar("PARTYCODE")), ''))), '') end),''),'')) AS VARCHAR))), '')) as link_hkey,
           MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_CLAIM|' || (nullif(trim(case when coalesce(nullif(trim(w0_claimno),''), nullif(trim("FOREIGN_KEY"),'')) is not null then coalesce(nullif(trim(w0_claimno), ''), nullif(trim("FOREIGN_KEY"), '')) end),'')) AS VARCHAR))), '')) as CLAIM_HKEY,
           MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (nullif(trim(case when coalesce(nullif(trim((nullif(trim(to_varchar("PARTYCODE")), ''))),'')) is not null then nullif(trim((nullif(trim(to_varchar("PARTYCODE")), ''))), '') end),'')) AS VARCHAR))), '')) as PARTY_HKEY
      from RAW.MAXIMUS_TRAVEL.NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_PARTY
     where MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_CLAIM|' || (nullif(trim(case when coalesce(nullif(trim(w0_claimno),''), nullif(trim("FOREIGN_KEY"),'')) is not null then coalesce(nullif(trim(w0_claimno), ''), nullif(trim("FOREIGN_KEY"), '')) end),'')) AS VARCHAR))), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (nullif(trim(case when coalesce(nullif(trim((nullif(trim(to_varchar("PARTYCODE")), ''))),'')) is not null then nullif(trim((nullif(trim(to_varchar("PARTYCODE")), ''))), '') end),'')) AS VARCHAR))), '')) is not null
       and (claim_party_bk is not null)
    union all
    -- via lnkfeed_mt_claim_party <- stg2_mt__clm_clmd_clmrsk_party
    select 'lnkfeed_mt_claim_party <- stg2_mt__clm_clmd_clmrsk_party' as src_feed,
           MD5_BINARY(NULLIF(UPPER(TRIM(CAST('LNK_CLAIM_PARTY|' || (coalesce(nullif(trim(case when coalesce(nullif(trim(w0_claimno),''), nullif(trim("FOREIGN_KEY"),'')) is not null then coalesce(nullif(trim(w0_claimno), ''), nullif(trim("FOREIGN_KEY"), '')) end),''),'') || '|' || coalesce(nullif(trim(case when coalesce(nullif(trim((nullif(trim(to_varchar("PARTYCODE")), ''))),'')) is not null then nullif(trim((nullif(trim(to_varchar("PARTYCODE")), ''))), '') end),''),'')) AS VARCHAR))), '')) as link_hkey,
           MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_CLAIM|' || (nullif(trim(case when coalesce(nullif(trim(w0_claimno),''), nullif(trim("FOREIGN_KEY"),'')) is not null then coalesce(nullif(trim(w0_claimno), ''), nullif(trim("FOREIGN_KEY"), '')) end),'')) AS VARCHAR))), '')) as CLAIM_HKEY,
           MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (nullif(trim(case when coalesce(nullif(trim((nullif(trim(to_varchar("PARTYCODE")), ''))),'')) is not null then nullif(trim((nullif(trim(to_varchar("PARTYCODE")), ''))), '') end),'')) AS VARCHAR))), '')) as PARTY_HKEY
      from RAW.MAXIMUS_TRAVEL.NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_RISK_PARTY
     where MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_CLAIM|' || (nullif(trim(case when coalesce(nullif(trim(w0_claimno),''), nullif(trim("FOREIGN_KEY"),'')) is not null then coalesce(nullif(trim(w0_claimno), ''), nullif(trim("FOREIGN_KEY"), '')) end),'')) AS VARCHAR))), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (nullif(trim(case when coalesce(nullif(trim((nullif(trim(to_varchar("PARTYCODE")), ''))),'')) is not null then nullif(trim((nullif(trim(to_varchar("PARTYCODE")), ''))), '') end),'')) AS VARCHAR))), '')) is not null
       and (claim_party_bk is not null)
)
select 'MAXIMUS' as project, 'LINK_CLAIM_PARTY' as link, src_feed, to_varchar(link_hkey, 'HEX') as missing_link_hkey,
       to_varchar(CLAIM_HKEY, 'HEX') as CLAIM_HKEY, to_varchar(PARTY_HKEY, 'HEX') as PARTY_HKEY
  from src
 where not exists (select 1 from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.LINK_CLAIM_PARTY l where l.CLAIM_PARTY_HKEY = src.link_hkey)
 order by src_feed
 limit 100;



----------------------------------------------------------------------------------------
-- 2. MAXIMUS — LINK_CLAIM_PARTY -- (b) orphan links (link FK -> hub)   [Implemented]  [M1]
-- Link rows scoped to RECORD_SOURCE 'MAXIMUS_%'; every FK must exist in its hub (any
-- project's rows -- shared vault). FKs: CLAIM_HKEY -> HUB_CLAIM, PARTY_HKEY ->
-- HUB_PARTY. Link rows scoped by RECORD_SOURCE value set (6 travel feeds) rather than
-- the shared 'MAXIMUS_' prefix.
----------------------------------------------------------------------------------------
select 'MAXIMUS' as project, 'LINK_CLAIM_PARTY' as link, 'CLAIM_HKEY' as fk_column, 'HUB_CLAIM' as hub,
       count(*) as link_rows,
       count_if(l.CLAIM_HKEY is null) as null_fk_rows,
       count_if(l.CLAIM_HKEY is not null and h.k is null) as orphan_fk_rows,
       array_slice(array_agg(distinct iff(l.CLAIM_HKEY is not null and h.k is null, to_varchar(l.CLAIM_HKEY, 'HEX'), null)), 0, 3) as orphan_examples,
       iff(null_fk_rows = 0 and orphan_fk_rows = 0, 'PASS', 'FAIL') as status
  from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.LINK_CLAIM_PARTY l
  left join (select distinct CLAIM_HKEY as k from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.HUB_CLAIM) h on h.k = l.CLAIM_HKEY
 where l.RECORD_SOURCE in ('MAXIMUS_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_ATTRIBUTE_PROPERTIES_PIVOT_VW', 'MAXIMUS_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_PARTY', 'MAXIMUS_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_PAYMENT', 'MAXIMUS_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_RESERVE', 'MAXIMUS_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_RISK_PARTY', 'MAXIMUS_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_RISK_RISK_ATTRIBUTE_MULTI_SET_PROPERTY_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW')
union all
select 'MAXIMUS' as project, 'LINK_CLAIM_PARTY' as link, 'PARTY_HKEY' as fk_column, 'HUB_PARTY' as hub,
       count(*) as link_rows,
       count_if(l.PARTY_HKEY is null) as null_fk_rows,
       count_if(l.PARTY_HKEY is not null and h.k is null) as orphan_fk_rows,
       array_slice(array_agg(distinct iff(l.PARTY_HKEY is not null and h.k is null, to_varchar(l.PARTY_HKEY, 'HEX'), null)), 0, 3) as orphan_examples,
       iff(null_fk_rows = 0 and orphan_fk_rows = 0, 'PASS', 'FAIL') as status
  from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.LINK_CLAIM_PARTY l
  left join (select distinct PARTY_HKEY as k from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.HUB_PARTY) h on h.k = l.PARTY_HKEY
 where l.RECORD_SOURCE in ('MAXIMUS_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_ATTRIBUTE_PROPERTIES_PIVOT_VW', 'MAXIMUS_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_PARTY', 'MAXIMUS_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_PAYMENT', 'MAXIMUS_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_RESERVE', 'MAXIMUS_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_RISK_PARTY', 'MAXIMUS_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_RISK_RISK_ATTRIBUTE_MULTI_SET_PROPERTY_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW')
order by fk_column;



----------------------------------------------------------------------------------------
-- 3. MAXIMUS — LINK_CLAIM_PARTY -- (c) unexpected links (link -> RAW)   [Informational]  [M1]
-- Not part of the pass criterion: link rows of this project whose relationship is no
-- longer in RAW. Link rows scoped by RECORD_SOURCE value set (6 travel feeds) rather
-- than the shared 'MAXIMUS_' prefix.
----------------------------------------------------------------------------------------
with src as (
    -- via lnkfeed_mt_claim_party <- stg2_mt__clm_clmd_clmap_pv
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('LNK_CLAIM_PARTY|' || (coalesce(nullif(trim(case when coalesce(nullif(trim((nullif(trim(to_varchar("CLAIMNO")), ''))),''), nullif(trim(w0_claimno),''), nullif(trim("FOREIGN_KEY"),'')) is not null then coalesce(nullif(trim((nullif(trim(to_varchar("CLAIMNO")), ''))), ''), nullif(trim(w0_claimno), ''), nullif(trim("FOREIGN_KEY"), '')) end),''),'') || '|' || coalesce(nullif(trim(case when coalesce(nullif(trim((nullif(trim(to_varchar("CLAIM_COURT_PARTY_CODE")), ''))),'')) is not null then nullif(trim((nullif(trim(to_varchar("CLAIM_COURT_PARTY_CODE")), ''))), '') end),''),'')) AS VARCHAR))), '')) as link_hkey,
           MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_CLAIM|' || (nullif(trim(case when coalesce(nullif(trim((nullif(trim(to_varchar("CLAIMNO")), ''))),''), nullif(trim(w0_claimno),''), nullif(trim("FOREIGN_KEY"),'')) is not null then coalesce(nullif(trim((nullif(trim(to_varchar("CLAIMNO")), ''))), ''), nullif(trim(w0_claimno), ''), nullif(trim("FOREIGN_KEY"), '')) end),'')) AS VARCHAR))), '')) as CLAIM_HKEY,
           MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (nullif(trim(case when coalesce(nullif(trim((nullif(trim(to_varchar("CLAIM_COURT_PARTY_CODE")), ''))),'')) is not null then nullif(trim((nullif(trim(to_varchar("CLAIM_COURT_PARTY_CODE")), ''))), '') end),'')) AS VARCHAR))), '')) as PARTY_HKEY
      from RAW.MAXIMUS_TRAVEL.NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_ATTRIBUTE_PROPERTIES_PIVOT_VW
     where MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_CLAIM|' || (nullif(trim(case when coalesce(nullif(trim((nullif(trim(to_varchar("CLAIMNO")), ''))),''), nullif(trim(w0_claimno),''), nullif(trim("FOREIGN_KEY"),'')) is not null then coalesce(nullif(trim((nullif(trim(to_varchar("CLAIMNO")), ''))), ''), nullif(trim(w0_claimno), ''), nullif(trim("FOREIGN_KEY"), '')) end),'')) AS VARCHAR))), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (nullif(trim(case when coalesce(nullif(trim((nullif(trim(to_varchar("CLAIM_COURT_PARTY_CODE")), ''))),'')) is not null then nullif(trim((nullif(trim(to_varchar("CLAIM_COURT_PARTY_CODE")), ''))), '') end),'')) AS VARCHAR))), '')) is not null
       and (claim_party_bk__claim_court_counterparty is not null)
    union all
    -- via lnkfeed_mt_claim_party <- stg2_mt__clm_clmd_clmrsk_rska_msp_msd_prop_pv
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('LNK_CLAIM_PARTY|' || (coalesce(nullif(trim(case when coalesce(nullif(trim(w0_claimno),''), nullif(trim("FOREIGN_KEY"),'')) is not null then coalesce(nullif(trim(w0_claimno), ''), nullif(trim("FOREIGN_KEY"), '')) end),''),'') || '|' || coalesce(nullif(trim(case when coalesce(nullif(trim((nullif(trim(to_varchar("CLAIMANT_PARTY_CODE")), ''))),'')) is not null then nullif(trim((nullif(trim(to_varchar("CLAIMANT_PARTY_CODE")), ''))), '') end),''),'')) AS VARCHAR))), '')) as link_hkey,
           MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_CLAIM|' || (nullif(trim(case when coalesce(nullif(trim(w0_claimno),''), nullif(trim("FOREIGN_KEY"),'')) is not null then coalesce(nullif(trim(w0_claimno), ''), nullif(trim("FOREIGN_KEY"), '')) end),'')) AS VARCHAR))), '')) as CLAIM_HKEY,
           MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (nullif(trim(case when coalesce(nullif(trim((nullif(trim(to_varchar("CLAIMANT_PARTY_CODE")), ''))),'')) is not null then nullif(trim((nullif(trim(to_varchar("CLAIMANT_PARTY_CODE")), ''))), '') end),'')) AS VARCHAR))), '')) as PARTY_HKEY
      from RAW.MAXIMUS_TRAVEL.NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_RISK_RISK_ATTRIBUTE_MULTI_SET_PROPERTY_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW
     where MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_CLAIM|' || (nullif(trim(case when coalesce(nullif(trim(w0_claimno),''), nullif(trim("FOREIGN_KEY"),'')) is not null then coalesce(nullif(trim(w0_claimno), ''), nullif(trim("FOREIGN_KEY"), '')) end),'')) AS VARCHAR))), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (nullif(trim(case when coalesce(nullif(trim((nullif(trim(to_varchar("CLAIMANT_PARTY_CODE")), ''))),'')) is not null then nullif(trim((nullif(trim(to_varchar("CLAIMANT_PARTY_CODE")), ''))), '') end),'')) AS VARCHAR))), '')) is not null
       and (claim_party_bk__claimant is not null)
    union all
    -- via lnkfeed_mt_claim_party <- stg2_mt__clm_clmd_clmrsk_rska_msp_msd_prop_pv
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('LNK_CLAIM_PARTY|' || (coalesce(nullif(trim(case when coalesce(nullif(trim(w0_claimno),''), nullif(trim("FOREIGN_KEY"),'')) is not null then coalesce(nullif(trim(w0_claimno), ''), nullif(trim("FOREIGN_KEY"), '')) end),''),'') || '|' || coalesce(nullif(trim(case when coalesce(nullif(trim((nullif(trim(to_varchar("PARTY_NAME_CODE")), ''))),'')) is not null then nullif(trim((nullif(trim(to_varchar("PARTY_NAME_CODE")), ''))), '') end),''),'')) AS VARCHAR))), '')) as link_hkey,
           MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_CLAIM|' || (nullif(trim(case when coalesce(nullif(trim(w0_claimno),''), nullif(trim("FOREIGN_KEY"),'')) is not null then coalesce(nullif(trim(w0_claimno), ''), nullif(trim("FOREIGN_KEY"), '')) end),'')) AS VARCHAR))), '')) as CLAIM_HKEY,
           MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (nullif(trim(case when coalesce(nullif(trim((nullif(trim(to_varchar("PARTY_NAME_CODE")), ''))),'')) is not null then nullif(trim((nullif(trim(to_varchar("PARTY_NAME_CODE")), ''))), '') end),'')) AS VARCHAR))), '')) as PARTY_HKEY
      from RAW.MAXIMUS_TRAVEL.NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_RISK_RISK_ATTRIBUTE_MULTI_SET_PROPERTY_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW
     where MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_CLAIM|' || (nullif(trim(case when coalesce(nullif(trim(w0_claimno),''), nullif(trim("FOREIGN_KEY"),'')) is not null then coalesce(nullif(trim(w0_claimno), ''), nullif(trim("FOREIGN_KEY"), '')) end),'')) AS VARCHAR))), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (nullif(trim(case when coalesce(nullif(trim((nullif(trim(to_varchar("PARTY_NAME_CODE")), ''))),'')) is not null then nullif(trim((nullif(trim(to_varchar("PARTY_NAME_CODE")), ''))), '') end),'')) AS VARCHAR))), '')) is not null
       and (claim_party_bk__expense_line_party is not null)
    union all
    -- via lnkfeed_mt_claim_party <- stg2_mt__clm_clmd_clmrsk_rska_msp_msd_prop_pv
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('LNK_CLAIM_PARTY|' || (coalesce(nullif(trim(case when coalesce(nullif(trim(w0_claimno),''), nullif(trim("FOREIGN_KEY"),'')) is not null then coalesce(nullif(trim(w0_claimno), ''), nullif(trim("FOREIGN_KEY"), '')) end),''),'') || '|' || coalesce(nullif(trim(case when coalesce(nullif(trim((nullif(trim(to_varchar("PAYEE_CODE")), ''))),'')) is not null then nullif(trim((nullif(trim(to_varchar("PAYEE_CODE")), ''))), '') end),''),'')) AS VARCHAR))), '')) as link_hkey,
           MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_CLAIM|' || (nullif(trim(case when coalesce(nullif(trim(w0_claimno),''), nullif(trim("FOREIGN_KEY"),'')) is not null then coalesce(nullif(trim(w0_claimno), ''), nullif(trim("FOREIGN_KEY"), '')) end),'')) AS VARCHAR))), '')) as CLAIM_HKEY,
           MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (nullif(trim(case when coalesce(nullif(trim((nullif(trim(to_varchar("PAYEE_CODE")), ''))),'')) is not null then nullif(trim((nullif(trim(to_varchar("PAYEE_CODE")), ''))), '') end),'')) AS VARCHAR))), '')) as PARTY_HKEY
      from RAW.MAXIMUS_TRAVEL.NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_RISK_RISK_ATTRIBUTE_MULTI_SET_PROPERTY_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW
     where MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_CLAIM|' || (nullif(trim(case when coalesce(nullif(trim(w0_claimno),''), nullif(trim("FOREIGN_KEY"),'')) is not null then coalesce(nullif(trim(w0_claimno), ''), nullif(trim("FOREIGN_KEY"), '')) end),'')) AS VARCHAR))), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (nullif(trim(case when coalesce(nullif(trim((nullif(trim(to_varchar("PAYEE_CODE")), ''))),'')) is not null then nullif(trim((nullif(trim(to_varchar("PAYEE_CODE")), ''))), '') end),'')) AS VARCHAR))), '')) is not null
       and (claim_party_bk__payee is not null)
    union all
    -- via lnkfeed_mt_claim_party <- stg2_mt__clm_clmd_clmrsk_rska_msp_msd_prop_pv
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('LNK_CLAIM_PARTY|' || (coalesce(nullif(trim(case when coalesce(nullif(trim(w0_claimno),''), nullif(trim("FOREIGN_KEY"),'')) is not null then coalesce(nullif(trim(w0_claimno), ''), nullif(trim("FOREIGN_KEY"), '')) end),''),'') || '|' || coalesce(nullif(trim(case when coalesce(nullif(trim((nullif(trim(to_varchar("EXPENSE_PAYEE_PARTY_CODE")), ''))),'')) is not null then nullif(trim((nullif(trim(to_varchar("EXPENSE_PAYEE_PARTY_CODE")), ''))), '') end),''),'')) AS VARCHAR))), '')) as link_hkey,
           MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_CLAIM|' || (nullif(trim(case when coalesce(nullif(trim(w0_claimno),''), nullif(trim("FOREIGN_KEY"),'')) is not null then coalesce(nullif(trim(w0_claimno), ''), nullif(trim("FOREIGN_KEY"), '')) end),'')) AS VARCHAR))), '')) as CLAIM_HKEY,
           MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (nullif(trim(case when coalesce(nullif(trim((nullif(trim(to_varchar("EXPENSE_PAYEE_PARTY_CODE")), ''))),'')) is not null then nullif(trim((nullif(trim(to_varchar("EXPENSE_PAYEE_PARTY_CODE")), ''))), '') end),'')) AS VARCHAR))), '')) as PARTY_HKEY
      from RAW.MAXIMUS_TRAVEL.NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_RISK_RISK_ATTRIBUTE_MULTI_SET_PROPERTY_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW
     where MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_CLAIM|' || (nullif(trim(case when coalesce(nullif(trim(w0_claimno),''), nullif(trim("FOREIGN_KEY"),'')) is not null then coalesce(nullif(trim(w0_claimno), ''), nullif(trim("FOREIGN_KEY"), '')) end),'')) AS VARCHAR))), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (nullif(trim(case when coalesce(nullif(trim((nullif(trim(to_varchar("EXPENSE_PAYEE_PARTY_CODE")), ''))),'')) is not null then nullif(trim((nullif(trim(to_varchar("EXPENSE_PAYEE_PARTY_CODE")), ''))), '') end),'')) AS VARCHAR))), '')) is not null
       and (claim_party_bk__expense_payee is not null)
