    select 'lnkfeed_mt_party_role <- stg2_mt__uwr_pol_ins_mbr_pp_sp_pv' as src_feed,
           MD5_BINARY(NULLIF(UPPER(TRIM(CAST('LNK_PARTY_ROLE|' || (coalesce(nullif(trim(case when coalesce(nullif(trim(w0_party_code),'')) is not null then nullif(trim(w0_party_code), '') end),''),'') || '|' || coalesce(coalesce(nullif(trim((nullif(trim(to_varchar("PARTY_FUNCTION")), ''))), ''),''),'')) AS VARCHAR))), '')) as link_hkey,
           MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (nullif(trim(case when coalesce(nullif(trim(w0_party_code),'')) is not null then nullif(trim(w0_party_code), '') end),'')) AS VARCHAR))), '')) as PARTY_HKEY,
           coalesce(nullif(trim((nullif(trim(to_varchar("PARTY_FUNCTION")), ''))), ''),'') as PARTY_ROLE_ROLE
      from RAW.MAXIMUS_TRAVEL.NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_MEMBER_DETAILS_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
     where MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (nullif(trim(case when coalesce(nullif(trim(w0_party_code),'')) is not null then nullif(trim(w0_party_code), '') end),'')) AS VARCHAR))), '')) is not null
       and coalesce(nullif(trim((nullif(trim(to_varchar("PARTY_FUNCTION")), ''))), ''),'') is not null
       and (party_role_bk__insured_member is not null)
)
select 'MAXIMUS' as project, 'LINK_PARTY_ROLE' as link,
       coalesce(src.src_feed, '== TOTAL (distinct across feeds) ==') as src_feed,
       count(distinct src.link_hkey) as source_relationships,
       count(distinct iff(l.k is not null, src.link_hkey, null)) as present_in_link,
       source_relationships - present_in_link as missing_links,
       iff(missing_links = 0, 'PASS', 'FAIL') as status
  from src
  left join (select distinct PARTY_ROLE_HKEY as k from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.LINK_PARTY_ROLE) l on l.k = src.link_hkey
 group by grouping sets ((src.src_feed), ())
 order by grouping(src.src_feed) desc, src.src_feed;

