----------------------------------------------------------------------------------------
-- 8. MAXIMUS — LINK_PARTY_ROLE -- (b) orphan links (link FK -> hub)   [Implemented]  [M2]
-- Link rows scoped to RECORD_SOURCE 'MAXIMUS_%'; every FK must exist in its hub (any
-- project's rows -- shared vault). FKs: PARTY_HKEY -> HUB_PARTY, PARTY_ROLE_ROLE ->
-- HUB_PARTY_ROLE_ROLE. Link rows scoped by RECORD_SOURCE value set (5 travel feeds)
-- rather than the shared 'MAXIMUS_' prefix.
----------------------------------------------------------------------------------------
select 'MAXIMUS' as project, 'LINK_PARTY_ROLE' as link, 'PARTY_HKEY' as fk_column, 'HUB_PARTY' as hub,
       count(*) as link_rows,
       count_if(l.PARTY_HKEY is null) as null_fk_rows,
       count_if(l.PARTY_HKEY is not null and h.k is null) as orphan_fk_rows,
       array_slice(array_agg(distinct iff(l.PARTY_HKEY is not null and h.k is null, to_varchar(l.PARTY_HKEY, 'HEX'), null)), 0, 3) as orphan_examples,
       iff(null_fk_rows = 0 and orphan_fk_rows = 0, 'PASS', 'FAIL') as status
  from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.LINK_PARTY_ROLE l
  left join (select distinct PARTY_HKEY as k from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.HUB_PARTY) h on h.k = l.PARTY_HKEY
 where l.RECORD_SOURCE in ('MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_MEMBER_DETAILS_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW', 'MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_RISK_PROPERTY_MULTI_SET_PROPERTY_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW', 'MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_POLICY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW', 'MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_QUOTE_PARAM_DETAILS_POLICY_PROPERTY_RULE_LIST_PIVOT_VW', 'MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_QUOTE_PARAM_DETAILS_RISK_LIST_MULTI_SET_PROPERTY_INPUT_MULTI_SET_DETAIL_INPUT_PROPERTY_PIVOT_VW')
union all
select 'MAXIMUS' as project, 'LINK_PARTY_ROLE' as link, 'PARTY_ROLE_ROLE' as fk_column, 'HUB_PARTY_ROLE_ROLE' as hub,
       count(*) as link_rows,
       count_if(l.PARTY_ROLE_ROLE is null) as null_fk_rows,
       count_if(l.PARTY_ROLE_ROLE is not null and h.k is null) as orphan_fk_rows,
       array_slice(array_agg(distinct iff(l.PARTY_ROLE_ROLE is not null and h.k is null, to_varchar(l.PARTY_ROLE_ROLE, 'HEX'), null)), 0, 3) as orphan_examples,
       iff(null_fk_rows = 0 and orphan_fk_rows = 0, 'PASS', 'FAIL') as status
  from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.LINK_PARTY_ROLE l
  left join (select distinct PARTY_ROLE_ROLE_HKEY as k from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.HUB_PARTY_ROLE_ROLE) h on h.k = l.PARTY_ROLE_ROLE
 where l.RECORD_SOURCE in ('MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_MEMBER_DETAILS_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW', 'MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_RISK_PROPERTY_MULTI_SET_PROPERTY_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW', 'MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_POLICY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW', 'MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_QUOTE_PARAM_DETAILS_POLICY_PROPERTY_RULE_LIST_PIVOT_VW', 'MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_QUOTE_PARAM_DETAILS_RISK_LIST_MULTI_SET_PROPERTY_INPUT_MULTI_SET_DETAIL_INPUT_PROPERTY_PIVOT_VW')
order by fk_column;



