select 'MAXIMUS' as project, 'LINK_PARTY_ROLE' as link, l.RECORD_SOURCE,
       count(*) as link_rows,
       count_if(k.link_hkey is null) as unexpected_links,
       array_slice(array_agg(iff(k.link_hkey is null, to_varchar(l.PARTY_ROLE_HKEY, 'HEX'), null)), 0, 3) as examples
  from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.LINK_PARTY_ROLE l
  left join (select distinct link_hkey from src) k on k.link_hkey = l.PARTY_ROLE_HKEY
 where l.RECORD_SOURCE in ('MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_MEMBER_DETAILS_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW', 'MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_RISK_PROPERTY_MULTI_SET_PROPERTY_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW', 'MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_POLICY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW', 'MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_QUOTE_PARAM_DETAILS_POLICY_PROPERTY_RULE_LIST_PIVOT_VW', 'MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_QUOTE_PARAM_DETAILS_RISK_LIST_MULTI_SET_PROPERTY_INPUT_MULTI_SET_DETAIL_INPUT_PROPERTY_PIVOT_VW')
 group by l.RECORD_SOURCE
 order by l.RECORD_SOURCE;



