select 'MAXIMUS' as project, 'LINK_POLICY_PARTY' as link, src_feed, to_varchar(link_hkey, 'HEX') as missing_link_hkey,
       to_varchar(POLICY_HKEY, 'HEX') as POLICY_HKEY, to_varchar(PARTY_HKEY, 'HEX') as PARTY_HKEY
  from src
 where not exists (select 1 from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.LINK_POLICY_PARTY l where l.POLICY_PARTY_HKEY = src.link_hkey)
 order by src_feed
 limit 100;



----------------------------------------------------------------------------------------
-- 11. MAXIMUS — LINK_POLICY_PARTY -- (b) orphan links (link FK -> hub)   [Implemented]  [M3]
-- Link rows scoped to RECORD_SOURCE 'MAXIMUS_%'; every FK must exist in its hub (any
-- project's rows -- shared vault). FKs: POLICY_HKEY -> HUB_POLICY, PARTY_HKEY ->
-- HUB_PARTY. Link rows scoped by RECORD_SOURCE value set (5 travel feeds) rather than
-- the shared 'MAXIMUS_' prefix.
----------------------------------------------------------------------------------------
select 'MAXIMUS' as project, 'LINK_POLICY_PARTY' as link, 'POLICY_HKEY' as fk_column, 'HUB_POLICY' as hub,
       count(*) as link_rows,
       count_if(l.POLICY_HKEY is null) as null_fk_rows,
       count_if(l.POLICY_HKEY is not null and h.k is null) as orphan_fk_rows,
       array_slice(array_agg(distinct iff(l.POLICY_HKEY is not null and h.k is null, to_varchar(l.POLICY_HKEY, 'HEX'), null)), 0, 3) as orphan_examples,
       iff(null_fk_rows = 0 and orphan_fk_rows = 0, 'PASS', 'FAIL') as status
  from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.LINK_POLICY_PARTY l
  left join (select distinct POLICY_HKEY as k from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.HUB_POLICY) h on h.k = l.POLICY_HKEY
 where l.RECORD_SOURCE in ('MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_MEMBER_DETAILS', 'MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_MEMBER_DETAILS_PARTY_RELATION', 'MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_POLICY_RELATION', 'MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_PROPOSER_DETAILS', 'MAXIMUS_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_PROPOSER_DETAILS_PARTY_RELATION')
union all
select 'MAXIMUS' as project, 'LINK_POLICY_PARTY' as link, 'PARTY_HKEY' as fk_column, 'HUB_PARTY' as hub,
       count(*) as link_rows,
       count_if(l.PARTY_HKEY is null) as null_fk_rows,
       count_if(l.PARTY_HKEY is not null and h.k is null) as orphan_fk_rows,
       array_slice(array_agg(distinct iff(l.PARTY_HKEY is not null and h.k is null, to_varchar(l.PARTY_HKEY, 'HEX'), null)), 0, 3) as orphan_examples,
       iff(null_fk_rows = 0 and orphan_fk_rows = 0, 'PASS', 'FAIL') as status
